<?php session_start();require __DIR__.'/../config.php';require_admin();$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$title=trim($_POST['title']??'');$version=trim($_POST['version']??'');$author=trim($_POST['author']??'');$category=trim($_POST['category']??'');$game=trim($_POST['game']??'');$description=trim($_POST['description']??'');$requirements=trim($_POST['requirements']??'');if(!$title||!$version||!$author||!$category||!$game||!$description)$error='Please fill in every required field.';elseif(empty($_FILES['mod_file']['name'])||empty($_FILES['thumbnail']['name']))$error='A mod file and thumbnail are both required.';elseif($_FILES['mod_file']['error']!==UPLOAD_ERR_OK||$_FILES['thumbnail']['error']!==UPLOAD_ERR_OK)$error='One of the uploads failed.';elseif($_FILES['mod_file']['size']>MAX_MOD_SIZE)$error='The mod file is too large.';elseif($_FILES['thumbnail']['size']>MAX_THUMB_SIZE)$error='The thumbnail is too large.';else{$me=strtolower(pathinfo($_FILES['mod_file']['name'],PATHINFO_EXTENSION));$te=strtolower(pathinfo($_FILES['thumbnail']['name'],PATHINFO_EXTENSION));if(!in_array($me,['zip','7z','rar','apk','pak','obb'],true))$error='Allowed mod files: ZIP, 7Z, RAR, APK, PAK, OBB.';elseif(!in_array($te,['jpg','jpeg','png','webp'],true))$error='Allowed thumbnails: JPG, JPEG, WEBP.';elseif(!@getimagesize($_FILES['thumbnail']['tmp_name']))$error='The thumbnail is not a valid image.';else{ensure_storage();$mf=random_filename($me);$tf=random_filename($te);if(!move_uploaded_file($_FILES['mod_file']['tmp_name'],MOD_DIR.$mf))$error='Could not save the mod file.';elseif(!move_uploaded_file($_FILES['thumbnail']['tmp_name'],THUMB_DIR.$tf)){@unlink(MOD_DIR.$mf);$error='Could not save the thumbnail.';}else{$mods=load_mods();$id=next_id($mods);$mods[]=['id'=>$id,'title'=>$title,'version'=>$version,'author'=>$author,'category'=>$category,'game'=>$game,'description'=>$description,'requirements'=>$requirements,'filename'=>$mf,'original_filename'=>basename($_FILES['mod_file']['name']),'thumbnail'=>$tf,'file_size'=>(int)$_FILES['mod_file']['size'],'downloads'=>0,'created_at'=>date('c'),'updated_at'=>date('c')];if(save_mods($mods))$success='Mod uploaded successfully.';else{$error='Could not save metadata.';@unlink(MOD_DIR.$mf);@unlink(THUMB_DIR.$tf);}}}}}}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Upload Mod</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>body{background:#101114;color:#eee}.card{background:#181a1f}.form-control,.form-control:focus{background:#111318;color:#fff}</style></head><body><nav class="navbar navbar-dark border-bottom"><div class="container py-2"><a class="navbar-brand" href="index.php"><i class="bi bi-arrow-left"></i> Dashboard</a></div></nav><main class="container py-5"><div class="row justify-content-center"><div class="col-lg-9"><div class="card p-4"><h1><i class="bi bi-cloud-arrow-up"></i> Upload a Mod</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-8"><label class="form-label">Mod title *</label><input name="title" class="form-control" required></div><div class="col-md-4"><label class="form-label">Version *</label><input name="version" class="form-control" placeholder="1.0.0" required></div><div class="col-md-6"><label class="form-label">Author *</label><input name="author" class="form-control" required></div><div class="col-md-6"><label class="form-label">Game *</label><input name="game" class="form-control" required></div><div class="col-md-6"><label class="form-label">Category *</label><input name="category" class="form-control" placeholder="Vehicles, Maps, Textures..." required></div><div class="col-12"><label class="form-label">Description *</label><textarea name="description" rows="5" class="form-control" required></textarea></div><div class="col-12"><label class="form-label">Requirements</label><textarea name="requirements" rows="3" class="form-control"></textarea></div><div class="col-md-6"><label class="form-label">Mod file *</label><input type="file" name="mod_file" class="form-control" accept=".zip,.7z,.rar,.apk,.pak,.obb" required><small>Max 100 MB.</small></div><div class="col-md-6"><label class="form-label">Thumbnail *</label><input type="file" name="thumbnail" class="form-control" accept="image/jpeg,image/png,image/webp" required><small>JPG/PNG/WEBP, max 5 MB.</small></div><div class="col-12"><button class="btn btn-primary btn-lg"><i class="bi bi-upload"></i> Publish Mod</button></div></div></form></div></div></div></main></body></html>
